#include <iostream>
using namespace std;

const int MAXN = 10005;
int pushOrder[MAXN], target[MAXN], st[MAXN];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;
    for (int i = 0; i < n; i++) cin >> pushOrder[i];

    int t;
    cin >> t;
    while (t--) {
        for (int i = 0; i < n; i++) cin >> target[i];

        int top = -1, j = 0;
        for (int i = 0; i < n; i++) {
            st[++top] = pushOrder[i];
            while (top >= 0 && st[top] == target[j]) {
                top--;
                j++;
            }
        }
        cout << (top < 0 && j == n ? "yes\n" : "no\n");
    }
    return 0;
}
